import { SUDOKU_SIZE } from '@sudoku/constants';
import { decodeSencode, encodeSudoku } from '@sudoku/sencode';
import { generateSudoku } from '@sudoku/sudoku';
import { derived, writable } from 'svelte/store';
import { candidates } from './candidates';
import { hints } from './hints';
import { conflictKeysForGrid, createGame, createSudoku, nextSinglesHintForGrid, hasEmptyCell } from '../../../domain/index.js';

/*
 * Store 适配层（作业里推荐的方案 A）。
 * 组件只管 subscribe、调 userGrid.set / undo / redo；底下真正改棋的是 domain里的 Game。
 * Svelte 3 只吃「引用有没有换」，所以每次领域动完，都要 getGrid() 再 set 进 writable。
 */

function emptyGrid() {
	return Array.from({ length: SUDOKU_SIZE }, () => Array(SUDOKU_SIZE).fill(0));
}

function cloneGrid(g) {
	return g.map((row) => row.slice());
}

/** @type {ReturnType<typeof createGame> | null} */
let domainGame = null;

function createGrid() {
	const gridStore = writable(emptyGrid());

	return {
		subscribe: gridStore.subscribe,

		generate(difficulty) {
			gridStore.set(generateSudoku(difficulty));
		},

		decodeSencode(sencode) {
			gridStore.set(decodeSencode(sencode));
		},

		get(gridStore, x, y) {
			return gridStore[y][x];
		},

		getSencode(gridStore) {
			return encodeSudoku(gridStore);
		},
	};
}

export const grid = createGrid();

const userGridWritable = writable(emptyGrid());

export const canUndo = writable(false);
export const canRedo = writable(false);
export const exploring = writable(false);
/** 探索中若当前盘为已记录的失败终局，由适配层写入一句提示 */
export const exploreNotice = writable('');
export const singlesHintAvailable = writable(false);
export const canEnterExplore = writable(false);

grid.subscribe(($grid) => {
	domainGame = createGame({ sudoku: createSudoku(cloneGrid($grid)) });
	syncUserGridFromDomain();
});

/** 把领域里的当前盘抄到 store，顺带刷新撤销/重做的按钮状态 */
function syncUserGridFromDomain() {
	if (!domainGame) return;
	userGridWritable.set(domainGame.getSudoku().getGrid());
	canUndo.set(domainGame.canUndo());
	canRedo.set(domainGame.canRedo());
	const exp = domainGame.isExploring();
	exploring.set(exp);
	const g = domainGame.getSudoku().getGrid();
	singlesHintAvailable.set(nextSinglesHintForGrid(g) !== null);
	canEnterExplore.set(
		conflictKeysForGrid(g).length === 0 &&
			hasEmptyCell(g) &&
			nextSinglesHintForGrid(g) === null &&
			!exp,
	);
	if (exp && domainGame.isKnownFailedBoard()) {
		exploreNotice.set('当前盘面与某次探索中出现的冲突局面相同（失败路径记忆）');
	} else {
		exploreNotice.set('');
	}
}

function withDomainSync(run) {
	if (!domainGame) return;
	run();
	syncUserGridFromDomain();
}

function createUserGrid() {
	return {
		subscribe: userGridWritable.subscribe,

		set(pos, value) {
			withDomainSync(() => {
				domainGame.guess({ row: pos.y, col: pos.x, value });
			});
		},

		/**
		 * 「下一步提示」：在存在唯一候选格时填上该数（一步一记 history，与 HW1 一致）。
		 * @returns {boolean} 是否成功应用
		 */
		applySinglesHint() {
			let applied = false;
			withDomainSync(() => {
				const hint = domainGame.getSudoku().getNextSinglesHint();
				if (!hint) return;
				hints.useHint();
				domainGame.guess({ row: hint.row, col: hint.col, value: hint.value });
				applied = true;
			});
			return applied;
		},

		/**
		 * 「候选提示」：把当前格在领域中的候选数写入 notes 候选 UI（不自动填数）。
		 * @returns {boolean} 是否写入了非空候选
		 */
		applyCandidateHint(pos) {
			if (!domainGame) return false;
			const list = domainGame.getSudoku().getCellCandidates(pos.y, pos.x);
			if (list.length === 0) return false;
			hints.useHint();
			candidates.setFromHint(pos, list);
			return true;
		},

		undo() {
			withDomainSync(() => {
				domainGame.undo();
			});
		},

		redo() {
			withDomainSync(() => {
				domainGame.redo();
			});
		},

		canUndo() {
			return domainGame ? domainGame.canUndo() : false;
		},

		canRedo() {
			return domainGame ? domainGame.canRedo() : false;
		},

		enterExplore() {
			let result = { ok: false, reason: 'no_game' };
			withDomainSync(() => {
				result = domainGame.enterExplore();
			});
			return result;
		},

		abandonExplore() {
			let result = { ok: false, reason: 'no_game' };
			withDomainSync(() => {
				result = domainGame.abandonExplore();
			});
			return result;
		},

		commitExplore() {
			let result = { ok: false, reason: 'no_game' };
			withDomainSync(() => {
				result = domainGame.commitExplore();
			});
			return result;
		},

		backtrackExploreToAnchor() {
			let result = { ok: false, reason: 'no_game' };
			withDomainSync(() => {
				result = domainGame.backtrackExploreToAnchor();
			});
			return result;
		},
	};
}

export const userGrid = createUserGrid();

export const invalidCells = derived(userGridWritable, ($userGrid) => conflictKeysForGrid($userGrid), []);

export function createGameStore() {
	return { grid, userGrid, invalidCells };
}
